// === Tab: mySketch ===
let m = 360;

int [][] x = new Array(m)[8];
int [][] l = new Array(m)[8];
int [][] sw = new int [m][8];
int [][] c = new Array(m)[8];
let rgb = new Array(6);

function setup(){
  createCanvas(920, 690);
  background(0);
	colorMode(HSB,360,100,100);
  strokeWeight(10);

  stroke(255,255,0);

   for(i = 0; i<m; i++){
     for(k = 0; k < 8; k++){
       x[i][k]=k*70+int(random(-10,10));
       l[i][k]=int(random(5,40));
       sw[i][k] = int(random(0.25,1.5));
			 c[i][k] = int(random(6));
     }
   }

	 rgb[0]="#E9FA0A";
   rgb[1]="#FFFFFF";
   rgb[2]="#F2D10F";
   rgb[3]="#F9FA14";
   rgb[4]="#FFC905";
   rgb[5]="#D1A60B"; 

}



function draw(){
    fill(0,6);
	  noStroke();
    rect(0,0,width,height);
    translate(width/2,height/2);
    //ellipse(0,0,100,100);
    stroke(255,255,0);
    for(alpha=0; alpha <m; alpha++){
      rotate(radians(360/m));
      for(k =0; k < 8; k++){
        x[alpha][k]+=5;
        if ((x[alpha][k])+(l[alpha][k]) > 700){
          x[alpha][k] = 0;
        }
        strokeWeight(sw[alpha][k]);
        strokeWeight(2);
				stroke((frameCount/6+alpha)%360,100,100);
        line(x[alpha][k],0,x[alpha][k]+l[alpha][k],0);
      }
    }
}

